 vormen het perspectief op de strijd tegen apartheid en de ingrijpende veranderingen in Zuid-Afrika. Het persoonlijke leven en de geschiedenis van het land blijven daarbij met elkaar verbonden. De autobiografie onderzoekt hoe iemand door opeenvolgende ervaringen groeit in zijn overtuigingen en verantwoordelijkheid, terwijl vrijheid nog lang geen vanzelfsprekendheid is.","work_id":978100031,"evidence":[{"url":"https://metadata.isbn.nl/114839/de-lange-weg-naar-de-vrijheid.html","fact":"Paperback ISBN 9789045048048 verschijningsdatum 15/09/2022 NUR 321 Biografieen literaire auteurs imprint Atlas Contact uitgever Atlas Contact, Uitgeverij taal Nederlands","sha256":"90fd238783dc5f3a8ecc1356bc917b0f71b798f152ab98c18e67e42b3df4cef2","checkedAt":"2026-11-01T20:41:49.580Z","sourceAuthors":"Nelson Mandela"},{"url":"https://metadata.isbn.nl/114839/de-lange-weg-naar-de-vrijheid.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/114839/de-lange-weg-naar-de-vrijheid.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-04-20261101","review_status":"approved","bound_author_id":978300016},"before_row":null},{"key":{"id":978200129},"seq":4,"relation":"editions","after_row":{"id":978200129,"title":"De wildernis in","isbn_10":null,"isbn_13":"9789044615623","work_id":978100032,"cover_id":null,"language":"nld","publisher":"Prometheus, Uitgeverij","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200129},"seq":5,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":978100032,"evidence":[{"url":"https://metadata.isbn.nl/379810/de-wildernis-in.html","fact":"Paperback