akauer"},{"url":"https://metadata.isbn.nl/379810/de-wildernis-in.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/379810/de-wildernis-in.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-04-20261101","review_status":"approved","bound_author_id":978300017},"before_row":null},{"key":{"id":978200130},"seq":7,"relation":"editions","after_row":{"id":978200130,"title":"Het heelal","isbn_10":null,"isbn_13":"9789044618099","work_id":978100033,"cover_id":null,"language":"nld","publisher":"Prometheus","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200130},"seq":8,"relation":"catalog_edition_metadata","after_row":{"format":"paperback","work_id":978100033,"evidence":[{"url":"https://metadata.isbn.nl/1757765/het-heelal.html","fact":"Paperback ISBN 9789044618099 verschijningsdatum 12/02/2024 NUR 924 Natuurkunde algemeen imprint Prometheus uitgever Prometheus, Uitgeverij taal Nederlands","sha256":"25efb0be9e19862585dd1a0cfed5fdfbae2f79aea1911c7a913f3b14f6f9121f","checkedAt":"2026-11-01T20:46:32.562Z","sourceAuthors":"Stephen Hawking"},{"url":"https://metadata.isbn.nl/ie_fcache/0000642663_Het_heelal_0_0.jpg","fact":"Exact edition block and human visual review; same observed provider image stem for medium variant.","bytes":81849,"sha256":"4b2eb99c41be99dcf59468d8578e96f4e999f79a26865dc26f98d777c494fa86","checkedAt":"2026-11-01T21:23:02.935Z"},{"url":"https://uitgeverijprometheus.nl/boeken/heelal-paperback-2/","fact":"Het heelal9789044618099 is A Brief History of Time; not A Briefer History or children’s George series.","checkedAt":"2026-11-01"}],"cover_url":"https://metadata.isb