 en gezondheid. Ze opent met een verbeeld Amerikaans stadje waar het verdwijnen van dieren en onbekende ziekten het dagelijks leven ontregelen. Van daaruit kijkt ze naar de schade die middelen als DDT kunnen aanrichten. Haar betoog bevraagt het idee dat technische beheersing van ongedierte los kan worden gezien van de samenhang binnen een leefomgeving.","work_id":978100034,"evidence":[{"url":"https://metadata.isbn.nl/1571699/verstild-voorjaar.html","fact":"Paperback ISBN 9789025314675 verschijningsdatum 13/12/2022 NUR 320 Literaire non-fictie algemeen imprint Athenaeum uitgever Singel Uitgeverijen taal Nederlands","sha256":"6ede8c89b831fca983ce93307b617de003165330d3d6012f49e9ed88b0844be4","checkedAt":"2026-11-01T20:46:34.806Z","sourceAuthors":"Rachel Carson"},{"url":"https://metadata.isbn.nl/1571699/verstild-voorjaar.html","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://metadata.isbn.nl/1571699/verstild-voorjaar.html","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-04-20261101","review_status":"approved","bound_author_id":978300019},"before_row":null},{"key":{"id":978200132},"seq":13,"relation":"editions","after_row":{"id":978200132,"title":"Zwaarden, paarden en ziektekiemen","isbn_10":null,"isbn_13":"9789049801595","work_id":978100035,"cover_id":null,"language":"nld","publisher":"Uitgeverij Dwarsligger®","publish_date":null,"open_library_edition_id":null},"before_row":null},{"key":{"edition_id":978200132},"seq":14,"relation":"catalog_edition_metadata","after_row":{"format":"hardcover","work_id":978100035,"evidence":[{"url":"https://metadata.isbn.nl/24833/zwaarden-paarden-en-ziektekiemen.html","fact":"Hardback ISBN 9789049801595 versc