400913/de-kleine-prins-pop-up.html","review_batch":"nl007-reviewed-batch-04-20261101","review_status":"approved","bound_language":"nld","card_cover_url":null,"bound_author_id":978300022},"before_row":null},{"key":{"work_id":978100037,"language":"nl"},"seq":21,"relation":"catalog_work_descriptions","after_row":{"text":"Na een noodlanding in de woestijn ontmoet een piloot een jongen die van een kleine planeet afkomstig is. De kleine prins vertelt over zijn reizen en over de bewoners van andere werelden die hij heeft leren kennen. Hun ontmoetingen brengen vreemde gewoonten en verwachtingen aan het licht. Terwijl de piloot naar hem luistert, ontstaat een gesprek over verbondenheid en over wat volwassenen gemakkelijk uit het oog verliezen.","work_id":978100037,"evidence":[{"url":"https://metadata.isbn.nl/1400913/de-kleine-prins-pop-up.html","fact":"Hardback ISBN 9789061007036 verschijningsdatum 22/07/2015 NUR 302 Vertaalde literaire roman, novelle uitgever Donker B.V., Uitgeversmaatschappij Ad. taal Nederlands","sha256":"aa6291a6e5637a1b5dec7d9bd1d59992ecd93a93e4d27f917cc573ed91defc79","checkedAt":"2026-11-01T21:20:01.631Z","sourceAuthors":"Antoine de Saint Exupéry , Antoine de Saint-Exupery"},{"url":"https://www.bibliotheek.nl/catalogus/titel.444200568.html/de-kleine-prins/","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content.","checkedAt":"2026-11-01T21:37:32Z"}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://www.bibliotheek.nl/catalogus/titel.444200568.html/de-kleine-prins/","reviewed_at":"2026-11-01T21:37:32+00:00","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_type":"official_catalog","review_batch":"nl007-reviewed-batch-04-20261101","review_status":"approved","bound_author_id":978300022},"before_row":null},{"key":{"id":978200135},"seq":22,"relation":"editions","after_row":{"id":978200135,"title":"Alice in Wonderland","isbn