do $manifest_guard$ declare reviewed jsonb:='[{"relation":"editions","ref":"edition:9789045048048","key":{"id":978200128},"before":null,"after":{"id":978200128,"title":"De lange weg naar de vrijheid","isbn_10":null,"isbn_13":"9789045048048","work_id":978100031,"cover_id":null,"language":"nld","publisher":"Atlas Contact","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789045048048","key":{"edition_id":"@edition:9789045048048"},"before":null,"after":{"edition_id":"@edition:9789045048048","work_id":978100031,"bound_author_id":978300016,"bound_title":"De lange weg naar de vrijheid","bound_language":"nld","bound_isbn13":"9789045048048","format":"paperback","cover_url":"https://metadata.isbn.nl/ie_fcache/0000452797_De_lange_weg_naar_de_vrijheid_2_710_130_0_0.jpg","card_cover_url":null,"evidence_url":"https://metadata.isbn.nl/114839/de-lange-weg-naar-de-vrijheid.html","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/114839/de-lange-weg-naar-de-vrijheid.html","sha256":"90fd238783dc5f3a8ecc1356bc917b0f71b798f152ab98c18e67e42b3df4cef2","checkedAt":"2026-11-01T20:41:49.580Z","fact":"Paperback ISBN 9789045048048 verschijningsdatum 15/09/2022 NUR 321 Biografieen literaire auteurs imprint Atlas Contact uitgever Atlas Contact, Uitgeverij taal Nederlands","sourceAuthors":"Nelson Mandela"},{"url":"https://metadata.isbn.nl/ie_fcache/0000452797_De_lange_weg_naar_de_vrijheid_2_710_130_0_0.jpg","sha256":"08648d64ac1f9290dffdf711f394b844fc5241e255be6f192b3502ef3c52c6ac","bytes":127633,"checkedAt":"2026-11-01T21:23:00.322Z","fact":"Exact edition block and human visual review; same observed provider image stem for medium variant."}]}},{"relation":"catalog_work_descriptions","ref":"description:84","key":{"work_id":978100031,"language":"nl"},"before":null,"after":{"work_id":978100031,"language":"nl","bound_author_id":978300016,"text":"Nelson Mandela vertelt over de weg die hij aflegde van jongen tot politiek leider. Zijn eigen herinneringen vormen het perspectief op de strijd tegen apartheid en de ingrijpende veranderingen in Zuid-Afrika. Het persoonlijke leven en de geschiedenis van het land blijven daarbij met elkaar verbonden. De autobiografie onderzoekt hoe iemand door opeenvolgende ervaringen groeit in zijn overtuigingen en verantwoordelijkheid, terwijl vrijheid nog lang geen vanzelfsprekendheid is.","source_type":"official_catalog","source_name":"Bibliografische bron; oorspronkelijke gecontroleerde samenvatting","source_url":"https://metadata.isbn.nl/114839/de-lange-weg-naar-de-vrijheid.html","provenance":"original_source_reviewed_summary","review_status":"approved","reviewed_at":"2026-11-01T21:37:32Z","review_batch":"nl007-reviewed-batch-04-20261101","evidence":[{"url":"https://metadata.isbn.nl/114839/de-lange-weg-naar-de-vrijheid.html","sha256":"90fd238783dc5f3a8ecc1356bc917b0f71b798f152ab98c18e67e42b3df4cef2","checkedAt":"2026-11-01T20:41:49.580Z","fact":"Paperback ISBN 9789045048048 verschijningsdatum 15/09/2022 NUR 321 Biografieen literaire auteurs imprint Atlas Contact uitgever Atlas Contact, Uitgeverij taal Nederlands","sourceAuthors":"Nelson Mandela"},{"url":"https://metadata.isbn.nl/114839/de-lange-weg-naar-de-vrijheid.html","checkedAt":"2026-11-01T21:37:32Z","fact":"Work-bound content reviewed; original factual Dutch summary, not source quotation or title-derived content."}]}},{"relation":"editions","ref":"edition:9789044615623","key":{"id":978200129},"before":null,"after":{"id":978200129,"title":"De wildernis in","isbn_10":null,"isbn_13":"9789044615623","work_id":978100032,"cover_id":null,"language":"nld","publisher":"Prometheus, Uitgeverij","publish_date":null,"open_library_edition_id":null}},{"relation":"catalog_edition_metadata","ref":"metadata:9789044615623","key":{"edition_id":"@edition:9789044615623"},"before":null,"after":{"edition_id":"@edition:9789044615623",